<?php require_once __DIR__.'/../includes/functions.php';require_login('parent');$pdo=db();$uid=current_user()['id'];$s=$pdo->prepare('SELECT * FROM children WHERE parent_id=? ORDER BY full_name');$s->execute([$uid]);$children=$s->fetchAll();$s=$pdo->prepare("SELECT b.*,c.full_name child_name,h.name hospital_name,v.name vaccine_name FROM bookings b JOIN children c ON c.id=b.child_id JOIN hospitals h ON h.id=b.hospital_id JOIN vaccines v ON v.id=b.vaccine_id WHERE b.parent_id=? ORDER BY b.appointment_date DESC,b.appointment_time DESC");$s->execute([$uid]);$bookings=$s->fetchAll();$records=$pdo->prepare('SELECT r.*,c.full_name child_name,v.name vaccine_name,h.name hospital_name FROM vaccination_records r JOIN children c ON c.id=r.child_id JOIN vaccines v ON v.id=r.vaccine_id JOIN hospitals h ON h.id=r.hospital_id JOIN children c2 ON c2.id=r.child_id WHERE c2.parent_id=? ORDER BY r.administered_on DESC');$records->execute([$uid]);$history=$records->fetchAll();$hospitals=$pdo->query("SELECT id,name,city,address FROM hospitals WHERE status='active' ORDER BY name")->fetchAll();$vaccines=$pdo->query("SELECT id,name,dose,recommended_age FROM vaccines WHERE status='available' ORDER BY name")->fetchAll();$pageTitle='Parent dashboard';require __DIR__.'/../includes/header.php';?>
<div class="dashboard-head"><div><span class="eyebrow">PARENT PORTAL</span><h1>Hello, <?=e(current_user()['name'])?>.</h1><p>Keep your children's vaccination journey organised.</p></div></div><div class="stat-grid"><div class="stat-card"><small>Children</small><strong><?=count($children)?></strong><span>Profiles managed</span></div><div class="stat-card"><small>Appointments</small><strong><?=count($bookings)?></strong><span>Requests and bookings</span></div><div class="stat-card"><small>Upcoming</small><strong><?=count(array_filter($bookings,fn($b)=>$b['appointment_date']>=date('Y-m-d')&&in_array($b['status'],['approved','requested'])))?></strong><span>Future appointments</span></div><div class="stat-card"><small>Vaccination records</small><strong><?=count($history)?></strong><span>Completed doses</span></div></div>
<section class="panel" id="add-child"><div class="panel-head"><div><h2>Add a child</h2><p>Enter accurate details so appointments can be associated with the right child.</p></div></div><form class="data-form" method="post" action="<?=BASE_URL?>/parent/actions.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_child"><label>Child's full name<input name="full_name" required maxlength="140"></label><label>Date of birth<input type="date" name="date_of_birth" required max="<?=date('Y-m-d')?>"></label><label>Gender<select name="gender" required><option value="female">Female</option><option value="male">Male</option><option value="other">Other</option></select></label><label>Guardian phone<input name="guardian_phone" maxlength="30" placeholder="Optional contact number"></label><label class="wide">Notes (optional)<textarea name="notes" rows="2" placeholder="Relevant notes for the appointment"></textarea></label><div class="wide"><button class="button primary">Save child profile →</button></div></form></section>
<section class="panel" id="book"><div class="panel-head"><div><h2>Request an appointment</h2><p>Choose a child, an active hospital, a vaccine, and a preferred date.</p></div></div><?php if(!$children):?><div class="notice">Add a child profile before requesting an appointment.</div><?php elseif(!$hospitals):?><div class="notice">There are no active hospitals in the directory yet. Ask the administrator to add and activate a hospital.</div><?php else:?><form class="data-form" method="post" action="<?=BASE_URL?>/parent/actions.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="book"><label>Child<select name="child_id" required><?php foreach($children as $c):?><option value="<?=$c['id']?>"><?=e($c['full_name'])?></option><?php endforeach;?></select></label><label>Hospital<select name="hospital_id" required><?php foreach($hospitals as $h):?><option value="<?=$h['id']?>"><?=e($h['name'].' · '.$h['city'])?></option><?php endforeach;?></select></label><label>Vaccine<select name="vaccine_id" required><?php foreach($vaccines as $v):?><option value="<?=$v['id']?>"><?=e($v['name'].' — '.$v['dose'])?></option><?php endforeach;?></select></label><label>Preferred date<input type="date" name="appointment_date" min="<?=date('Y-m-d')?>" required></label><label>Preferred time<input type="time" name="appointment_time" required></label><label>Note (optional)<input name="parent_note" maxlength="500" placeholder="Any helpful details"></label><div class="wide"><button class="button primary">Send appointment request →</button></div></form><?php endif;?></section>
<section class="panel"><div class="panel-head"><div><h2>My children</h2><p>Profiles associated with your account.</p></div></div><div class="table-wrap"><table><thead><tr><th>Child</th><th>Date of birth</th><th>Gender</th><th>Guardian phone</th></tr></thead><tbody><?php if(!$children):?><tr><td colspan="4" class="empty">No child profiles added yet.</td></tr><?php endif;foreach($children as $c):?><tr><td><b><?=e($c['full_name'])?></b></td><td><?=e($c['date_of_birth'])?></td><td><?=e(ucfirst($c['gender']))?></td><td><?=e($c['guardian_phone']??'—')?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><div class="panel-head"><div><h2>Appointment tracking</h2><p>Follow the latest status of each request.</p></div></div><div class="table-wrap"><table><thead><tr><th>Child</th><th>Vaccine</th><th>Hospital</th><th>Appointment</th><th>Status</th></tr></thead><tbody><?php if(!$bookings):?><tr><td colspan="5" class="empty">Your appointment requests will appear here.</td></tr><?php endif;foreach($bookings as $b):?><tr><td><?=e($b['child_name'])?></td><td><?=e($b['vaccine_name'])?></td><td><?=e($b['hospital_name'])?></td><td><?=e($b['appointment_date'])?> · <?=e(substr($b['appointment_time'],0,5))?></td><td><span class="badge <?=e($b['status'])?>"><?=e(ucfirst($b['status']))?></span></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><div class="panel-head"><div><h2>Vaccination history</h2><p>Records entered by hospitals after a completed vaccination.</p></div></div><div class="table-wrap"><table><thead><tr><th>Child</th><th>Vaccine</th><th>Hospital</th><th>Administered on</th><th>Certificate</th><th>Notes</th></tr></thead><tbody><?php if(!$history):?><tr><td colspan="6" class="empty">Completed vaccination records will appear here.</td></tr><?php endif;foreach($history as $r):?><tr><td><?=e($r['child_name'])?></td><td><?=e($r['vaccine_name'])?></td><td><?=e($r['hospital_name'])?></td><td><?=e($r['administered_on'])?></td><td><a class="button small secondary" target="_blank" href="<?=BASE_URL?>/certificate.php?id=<?=$r['id']?>">View certificate ↗</a></td><td><?=e($r['notes']??'—')?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
